(() => {
 'use strict';
 const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
 const ui=Object.fromEntries(['score','time','best','overlay','heading','message','start','pause','tag','hint'].map(id=>[id,document.getElementById(id)]));
 const W=900,H=510,keys=new Set();let state='ready',elapsed=0,score=0,best=0,objects=[],sparks=[],spawn=0,coin=0,last=0,player={x:450,y:458,w:32,h:22};
 try{best=Number(localStorage.getItem('neon-dodge-best'))||0}catch{}ui.best.textContent=String(best).padStart(4,'0');
 function overlay(tag,title,message,label){ui.overlay.classList.remove('hidden');ui.tag.textContent=tag;ui.heading.innerHTML=title;ui.message.textContent=message;ui.start.innerHTML=label+' <span>→</span>';ui.hint.textContent=state==='paused'?'PRESS SPACE TO RESUME':'PRESS SPACE TO START'}
 function start(){if(state==='paused'){state='playing';ui.overlay.classList.add('hidden');ui.pause.innerHTML='Ⅱ <span>Pause</span>';return}elapsed=0;score=0;objects=[];sparks=[];spawn=.4;coin=1;player.x=W/2;keys.clear();state='playing';ui.pause.disabled=false;ui.pause.innerHTML='Ⅱ <span>Pause</span>';ui.overlay.classList.add('hidden');updateHud()}
 function pause(){if(state!=='playing')return;state='paused';keys.clear();ui.pause.innerHTML='▶ <span>Resume</span>';overlay('TAKE A BREATHER','Game paused','Ready? Pick up where you left off.','Resume game')}
 function end(){state='over';keys.clear();ui.pause.disabled=true;const isRecord=Math.floor(score)>best;best=Math.max(best,Math.floor(score));try{localStorage.setItem('neon-dodge-best',String(best))}catch{}ui.best.textContent=String(best).padStart(4,'0');overlay(isRecord?'NEW RECORD!':'TRY AGAIN?','Oops, you got hit!','Score '+Math.floor(score)+' · Survived '+elapsed.toFixed(1)+' seconds.','Play again')}
 function updateHud(){ui.score.textContent=String(Math.floor(score)).padStart(4,'0');ui.time.textContent=elapsed.toFixed(1)+'s'}
 function update(dt){elapsed+=dt;score+=dt*10;let dir=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0);player.x=Math.max(20,Math.min(W-20,player.x+dir*510*dt));spawn-=dt;coin-=dt;const speed=175+Math.min(elapsed*5,290);if(spawn<=0){const width=30+Math.random()*65;objects.push({x:width/2+Math.random()*(W-width),y:-50,w:width,h:22+Math.random()*24,v:speed,type:'block'});spawn=Math.max(.22,.72-elapsed*.009)}if(coin<=0){objects.push({x:24+Math.random()*(W-48),y:-30,w:18,h:18,v:speed*.8,type:'coin'});coin=1.5+Math.random()*1.4}for(const o of objects){o.y+=o.v*dt;if(Math.abs(o.x-player.x)<(o.w+player.w)/2&&Math.abs(o.y-player.y)<(o.h+player.h)/2){if(o.type==='block'){end();return}score+=50;o.dead=true;for(let i=0;i<12;i++)sparks.push({x:o.x,y:o.y,vx:(Math.random()-.5)*240,vy:(Math.random()-.5)*240,life:.5})}}objects=objects.filter(o=>!o.dead&&o.y<H+60);for(const p of sparks){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}sparks=sparks.filter(p=>p.life>0);updateHud()}
 function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#111722';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#263345';ctx.lineWidth=.6;for(let x=0;x<=W;x+=45){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=(elapsed*30)%45;y<H;y+=45){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.fillStyle='#58e5ef08';ctx.fillRect(0,430,W,70);ctx.setLineDash([5,9]);ctx.strokeStyle='#58e5ef38';ctx.beginPath();ctx.moveTo(0,430);ctx.lineTo(W,430);ctx.stroke();ctx.setLineDash([]);const visible=state==='ready'?[{x:140,y:80,w:55,h:28,type:'block'},{x:730,y:270,w:80,h:25,type:'block'},{x:590,y:125,w:18,h:18,type:'coin'},{x:280,y:340,w:18,h:18,type:'coin'}]:objects;for(const o of visible){ctx.save();ctx.translate(o.x,o.y);ctx.fillStyle=o.type==='coin'?'#d8ff63':'#ff647b';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=15;if(o.type==='coin')ctx.rotate(Math.PI/4);ctx.fillRect(-o.w/2,-o.h/2,o.w,o.h);ctx.shadowBlur=0;ctx.fillStyle='#ffffff40';ctx.fillRect(-o.w/2+3,-o.h/2+3,o.w-6,3);ctx.restore()}ctx.shadowColor='#58e5ef';ctx.shadowBlur=22;ctx.fillStyle='#58e5ef';ctx.fillRect(player.x-player.w/2,player.y-player.h/2,player.w,player.h);ctx.shadowBlur=0;ctx.fillStyle='#d9ffff';ctx.fillRect(player.x-10,player.y-7,20,4);for(const p of sparks){ctx.globalAlpha=p.life*2;ctx.fillStyle='#d8ff63';ctx.fillRect(p.x,p.y,4,4)}ctx.globalAlpha=1}
 function frame(now){const dt=Math.min((now-last)/1000,.04);last=now;if(state==='playing')update(dt);draw();requestAnimationFrame(frame)}
 ui.start.addEventListener('click',start);ui.pause.addEventListener('click',()=>state==='paused'?start():pause());
 window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.code==='Space'&&!e.repeat){state==='playing'?pause():start();return}keys.add(e.key.startsWith('Arrow')?e.key:k)});window.addEventListener('keyup',e=>keys.delete(e.key.startsWith('Arrow')?e.key:e.key.toLowerCase()));window.addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
 for(const [id,key]of [['left','ArrowLeft'],['right','ArrowRight']]){const b=document.getElementById(id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(key)});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(key))}
 if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'control_neon_dodge',description:'Start a new game, pause, resume, or read the current score.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['start','pause','resume','status']}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['start','pause','resume','status'].includes(input.action))throw new Error('Invalid action');if(input.action==='start'){if(state==='paused')state='over';start()}if(input.action==='pause')pause();if(input.action==='resume'&&state==='paused')start();return {state,score:Math.floor(score),seconds:Number(elapsed.toFixed(1)),best}}})).catch(()=>{})}catch{}}
 requestAnimationFrame(frame);
})();
